PipelineCacheSources pipeline_cache_sources(ID3D12Device* device) {
    if (!device) return {};
    ID3D12Device* real = rt::d3d12_xs::device_proxy_real_device(device);
    if (!real) real = device;
    const Device* d = Device::from<Device>(real);
    if (!d) return {};
    const DeviceState& state = d->state();
    PipelineCacheSources out{state.pipeline_cache_loaded.seed_bytes, state.pipeline_cache_loaded.saved_bytes};
    if (state.pipeline_cache_checkpoints) {
        out.checkpoints = state.pipeline_cache_checkpoints->runs();
        out.checkpoint_saves = state.pipeline_cache_checkpoints->saves();
    }
    return out;
}

PipelineLibraryStats pipeline_library_stats(ID3D12Device* device) {
    if (!device) return {};
    ID3D12Device* real = rt::d3d12_xs::device_proxy_real_device(device);
    if (!real) real = device;
    const Device* d = Device::from<Device>(real);
    if (!d) return {};
    const DeviceState& state = d->state();
    return {state.gpl_parts_made.load(),           state.gpl_parts_cached.load(),    state.gpl_links.load(),
            state.gpl_links_cached.load(),         state.gpl_optimized_at_creation.load(),
            state.gpl_optimized_linked.load(),     state.gpl_optimized_swapped.load()};
}

bool wait_pipeline_library_work(ID3D12Device* device, unsigned timeout_ms) {
    if (!device) return false;
    ID3D12Device* real = rt::d3d12_xs::device_proxy_real_device(device);
    if (!real) real = device;
    Device* d = Device::from<Device>(real);
    return d && d->mutable_state().gpl_wait_idle(std::chrono::milliseconds(timeout_ms));
}

ImageMemoryStats image_memory_stats(ID3D12Device* device) {
    if (!device) return {};
    ID3D12Device* real = rt::d3d12_xs::device_proxy_real_device(device);
    if (!real) real = device;
    const Device* d = Device::from<Device>(real);
    if (!d) return {};
    // merge: textures share blocks of our suballocator (allocate_resource, its image pools); upstream's ImageMemory,
    // which nothing allocates from here, is counted too.
    const auto pools = d->state().suballocator.stats(~0u, true);
    ImageMemoryStats out{std::uint64_t(pools.blocks), pools.block_bytes, std::uint64_t(pools.allocations)};
    if (d->state().image_memory) {
        const auto stats = d->state().image_memory->stats();
        out.blocks += stats.blocks;
        out.block_bytes += stats.block_bytes;
        out.textures += stats.ranges;
    }
    return out;
}

bool read_arena(ID3D12Device* device, std::uint64_t va, void* out, std::size_t bytes) {
    if (!device || !out) return false;
    ID3D12Device* real = rt::d3d12_xs::device_proxy_real_device(device);
    if (!real) real = device;
    const Device* d = Device::from<Device>(real);
    if (!d || !d->state().arena.mapped || va > d->state().arena.size || bytes > d->state().arena.size - va) return false;
    std::memcpy(out, d->state().arena.mapped + va, bytes);
    return true;
}

namespace {
// LEONIDA_TITLE_HEAP_SYNC: sampler-heap slots in title memory whose bytes changed (a sync found them, or their heap
// is going and was zeroed). Each S# gets its sampler and the slot's reference, as CreateSampler gives them; an
// all-zero slot holds none. The slots are keyed by their title addresses, as every other sampler call on such a heap
// uses them in this mode.
void title_sampler_slots(ID3D12Device* real, std::uintptr_t first, std::uintptr_t end) {
    Device* d = Device::from<Device>(real);
    if (!d) return;
    DeviceState& state = d->mutable_state();
    for (std::uintptr_t slot = first; slot + kDescriptorSize <= end; slot += kDescriptorSize) {
        leonida::gfx10::SamplerWords words{};
        std::memcpy(words.data(), reinterpret_cast<const void*>(slot), sizeof(words));
        const bool empty = std::all_of(words.begin(), words.end(), [](std::uint32_t w) { return w == 0; });
        if (empty) state.clear_sampler_slots(slot, slot + kDescriptorSize);
        else state.bind_sampler_slot(words, slot);
    }
}

const leonida::BindlessSet* bindless_of(ID3D12Device* device) {
    if (!device) return nullptr;
    ID3D12Device* real = rt::d3d12_xs::device_proxy_real_device(device);
    const Device* d = Device::from<Device>(real ? real : device);
    return d ? d->bindless() : nullptr;
}
} // namespace

VkDescriptorSet bindless_set(ID3D12Device* device) {
    const leonida::BindlessSet* set = bindless_of(device);
    return set ? set->set() : VK_NULL_HANDLE;
}

BindlessStats bindless_stats(ID3D12Device* device) {
    BindlessStats stats;
    if (!device) return stats;
    ID3D12Device* real = rt::d3d12_xs::device_proxy_real_device(device);
    const Device* d = Device::from<Device>(real ? real : device);
    if (!d || !d->bindless()) return stats;
    stats.generations_made = d->bindless()->generations_made();
    stats.retired_pending = d->bindless()->retired_count();
    stats.device_idle_waits = d->state().bindless_idle_waits.load(std::memory_order_relaxed);
    return stats;
}

VkDescriptorSetLayout bindless_set_layout(ID3D12Device* device) {
    const leonida::BindlessSet* set = bindless_of(device);
    return set ? set->layout() : VK_NULL_HANDLE;
}

std::uint32_t bindless_hash_lookup(ID3D12Device* device, const std::uint32_t (&key)[8]) {
    const leonida::BindlessSet* set = bindless_of(device);
    return set ? set->table().lookup(key) : 0;
}

BindlessRoom bindless_room(ID3D12Device* device) {
    const leonida::BindlessSet* set = bindless_of(device);
    if (!set) return {};
    return {set->free_images(leonida::ImageDimension::dim_2d), set->free_samplers()};
}

PipelineCacheStats pipeline_cache_stats(ID3D12Device* device) {
    PipelineCacheStats stats{};
    if (!device) return stats;
    ID3D12Device* real = rt::d3d12_xs::device_proxy_real_device(device);
    Device* d = Device::from<Device>(real ? real : device);
    if (!d) return stats;
    DeviceState& state = d->mutable_state();
    stats.available = state.vulkan_1_3 && state.pipeline_cache() != VK_NULL_HANDLE;
    stats.created = state.pipelines_created;
    stats.hits = state.pipeline_cache_hits;
    stats.bytes = state.pipeline_cache_bytes();
    return stats;
}

WindowPresenter::WindowPresenter(IUnknown* device, std::unique_ptr<leonida::VulkanPresenter> presenter)
    : device_(device), presenter_(std::move(presenter)) {
    if (device_) device_->AddRef();
}

WindowPresenter::~WindowPresenter() {
    presenter_.reset();  // before the device it runs on
    if (device_) device_->Release();
}

namespace {
HRESULT present_result(VkResult result) {
    if (result == VK_SUCCESS) return S_OK;
    // Review I12: by name, and not every frame: a window that keeps failing (a lost surface, a full queue) printed a
    // line per Present. The first 5, then every 1000th with the count.
    static std::atomic<std::uint64_t> failures{0};
    const std::uint64_t n = ++failures;
    if (n <= 5 || n % 1000 == 0) {
        const char* name = leonida::detail::vk_result_name(result);
        std::fprintf(stderr, "[rt] d3d12: present failed (%s, VkResult %d); %llu present failures so far\n",
                     name ? name : "unnamed", int(result), static_cast<unsigned long long>(n));
    }
    if (result == VK_ERROR_DEVICE_LOST) return DXGI_ERROR_DEVICE_REMOVED;
    if (result == VK_ERROR_FORMAT_NOT_SUPPORTED) return DXGI_ERROR_UNSUPPORTED;
    return E_FAIL;
}
}  // namespace

HRESULT WindowPresenter::present(ID3D12Resource* back_buffer, UINT sync_interval, const D3D12_RECT* src_rect,
                                 bool tear) {
    if (!back_buffer) return E_INVALIDARG;
    const leonida::PresentRect rect = src_rect ? leonida::PresentRect{src_rect->left, src_rect->top, src_rect->right,
                                                                       src_rect->bottom}
                                               : leonida::PresentRect{};
    return present_result(presenter_->present(resource_id(back_buffer), sync_interval > 0, src_rect ? &rect : nullptr,
                                              tear));
}

bool WindowPresenter::present_splash(ID3D12Resource* image) {
    if (!image) return false;
    image->AddRef();
    std::shared_ptr<ID3D12Resource> owner(image, [](ID3D12Resource* p) { p->Release(); });
    return presenter_->present_splash(resource_id(image), std::move(owner));
}

bool WindowPresenter::tear_supported() const { return presenter_->tear_supported(); }
bool WindowPresenter::last_present_tore() const { return presenter_->last_present_tore(); }
std::uint64_t WindowPresenter::tear_presents() const { return presenter_->tear_presents(); }

HRESULT WindowPresenter::present_blank(UINT sync_interval) {
    return present_result(presenter_->present_blank(sync_interval > 0));
}

HRESULT WindowPresenter::present_planes(const leonida::PresentPlanes& planes, UINT sync_interval, bool tear) {
    // Batches held on console memory waits run before the present waits for the frame's work: their writer may come
    // from this thread after the present (five-star-recomp docs/d3d12x-shim.md, "Memory waits").
    release_memory_waits("present");
    return present_result(presenter_->present_planes(planes, sync_interval > 0, tear));
}

